function findReviewProposals(text){
  if(text.length>256*1024)return [];
  const lines=text.split('\n'),blocks=[];let state=0,start=0;
  for(let i=0;i<lines.length;i++){
    const line=lines[i],hasMarker=['<<<<<<< SEARCH','=======','>>>>>>> REPLACE'].some(marker=>line.includes(marker));
    if(!hasMarker)continue;
    if(state===0&&line==='<<<<<<< SEARCH'&&i>0&&/^File: .+/.test(lines[i-1])){start=i-1;state=1}
    else if(state===1&&line==='=======')state=2;
    else if(state===2&&line==='>>>>>>> REPLACE'){blocks.push(lines.slice(start,i+1).join('\n'));if(blocks.length>20)return [];state=0}
    else return []
  }
  return state===0?blocks:[]
}

function extractReviewProposal(text){const blocks=findReviewProposals(text);return blocks.length===1?blocks[0]:null}

