function saveUndoReference(map,key,chat,record){map.set(chat,record);try{const refs=Array.from(map,([id,r])=>[id,{id:r.id,workspace:r.workspace,file:r.file,files:Array.isArray(r.files)?r.files.map(f=>({file:f.file})):undefined}]);localStorage.setItem(key,JSON.stringify(refs));const history=JSON.parse(localStorage.getItem(key+'.history')||'[]');if(!Array.isArray(history))throw Error('Invalid undo history');const r=refs.find(e=>e[0]===chat)[1];if(!history.some(e=>Array.isArray(e)&&e[0]===chat&&e[1]?.id===r.id))history.push([chat,r]);localStorage.setItem(key+'.history',JSON.stringify(history))}catch{isaNotifications.show('Undo history could not be saved in this browser. The record remains on the server.') }}

function undoChoices(key,chat,current){try{const list=JSON.parse(localStorage.getItem(key+'.history')||'[]');const records=Array.isArray(list)?list.filter(e=>Array.isArray(e)&&e[0]===chat&&e[1]&&typeof e[1].id==='string'&&/^[a-f0-9]{48}$/.test(e[1].id)&&typeof e[1].workspace==='string').map(e=>e[1]):[];if(current&&!records.some(r=>r.id===current.id))records.push(current);return records.reverse()}catch{return current?[current]:[]}}

function undoPicker(records,onChange){const label=node('label','','Saved undo record'),select=node('select');for(const r of records){const option=node('option','',r.id+' · '+(r.file||r.files?.map(f=>f.file).join(', ')||'files'));option.value=r.id;select.append(option)}select.onchange=()=>onChange(records.find(r=>r.id===select.value));label.append(select);return {label,select}}

function currentApprovalMode(){const value=(chats.find(chat=>chat.id===activeChatId)?.settings||draftChatSettings).approvalMode;return Object.hasOwn(approvalModes,value)?value:'always'}

function renderApprovalMode(){const mode=currentApprovalMode();document.querySelector('#approvalModeLabel').textContent=approvalModes[mode];for(const button of approvalMenu.querySelectorAll('[data-approval-mode]'))button.setAttribute('aria-checked',String(button.dataset.approvalMode===mode))}

function closeApprovalMenu(restoreFocus=false){approvalMenu.hidden=true;approvalButton.setAttribute('aria-expanded','false');if(restoreFocus)approvalButton.focus()}

function saveApprovalMode(next){if(!Object.hasOwn(approvalModes,next))return false;const current=chats.find(chat=>chat.id===activeChatId);if(current){const settings={...defaultChatSettings(),...current.settings,approvalMode:next};if(!saveChats(chats.map(chat=>chat.id===current.id?{...chat,settings}:chat)))return false}else draftChatSettings={...draftChatSettings,approvalMode:next};renderApprovalMode();return true}

function localWorkspaceHeaders(){const headers={'Content-Type':'application/json'};if(location.protocol==='http:'&&location.hostname==='127.0.0.1'&&localExecKey)headers['X-ISA-Exec-Token']=localExecKey;return headers}

async function sendEncryptedUsage(chat,events){
  if(location.protocol!=='http:'||location.hostname!=='127.0.0.1'||!localExecKey||!Array.isArray(events))return;
  const calls=events.map(e=>e?.usage).filter(u=>u&&['input','output','total'].every(k=>Number.isSafeInteger(u[k])&&u[k]>=0)&&(u.cached===null||u.cached===undefined||(Number.isSafeInteger(u.cached)&&u.cached>=0))).map(u=>({input:u.input,output:u.output,total:u.total,cached:u.cached??null}));if(!calls.length)return;
  const truncated=calls.length>32,token=localExecKey;try{const response=await fetch('/api/actions/usage',{method:'POST',headers:{'Content-Type':'application/json','X-ISA-Exec-Token':token},body:JSON.stringify({chat,calls:calls.slice(0,32),truncated})});const data=await response.json();if(!response.ok||data.encryptedDetails!=='best_effort')throw Error('unavailable');}catch{isaNotifications.show('Encrypted token-usage audit was not recorded; check the local key, audit settings and storage.')}
}

function openLocalToken(){if(location.protocol!=='http:'||location.hostname!=='127.0.0.1'){isaNotifications.show('Never enter a local execution token in a remote preview. Open ISA directly at http://127.0.0.1.');return}const dialog=node('dialog','routing-consent'),form=node('form'),label=node('label','','Local execution token'),input=node('input'),status=node('p'),actions=node('div','dialog-actions'),close=node('button','secondary-action','Close'),clear=node('button','secondary-action','Clear token'),save=node('button','primary','Use token');input.type='password';input.autocomplete='off';input.maxLength=256;input.required=true;input.value=localExecKey;label.append(input);close.type=clear.type='button';save.type='submit';status.setAttribute('role','status');actions.append(close,clear,save);form.append(label,status,actions);dialog.append(node('h2','','Local workspace token'),node('p','','Enter ISA_WEB_EXEC_TOKEN for direct loopback access. It stays in this tab memory until cleared or reloaded and is not stored in a chat. This does not validate the token or enable a workspace. Do not share it with a model or remote preview.'),form);document.body.append(dialog);function finish(){dialog.close();dialog.remove()}close.onclick=finish;dialog.oncancel=e=>{e.preventDefault();finish()};clear.onclick=()=>{localExecKey='';input.value='';status.textContent='Token cleared from tab memory.'};form.onsubmit=e=>{e.preventDefault();if(!/^[!-~]{32,256}$/.test(input.value)){status.textContent='Token must be 32–256 printable ASCII characters without spaces.';return}localExecKey=input.value;finish()};dialog.showModal();input.focus()}

function openWorkspaceBindings(){
  if(location.protocol!=='http:'||location.hostname!=='127.0.0.1'){isaNotifications.show('Workspace inspection requires direct http://127.0.0.1 access. Do not enter the execution token in a remote preview.');return}
  const dialog=node('dialog','routing-consent'),form=node('form'),label=node('label','','Local execution token'),key=node('input'),status=node('p'),result=node('pre'),actions=node('div','dialog-actions'),close=node('button','secondary-action','Close'),submit=node('button','primary','Inspect workspaces');let closed=false,busy=false;
  key.type='password';key.autocomplete='off';key.maxLength=256;key.required=true;key.value=localExecKey;label.append(key);status.setAttribute('role','status');result.style.whiteSpace='pre-wrap';result.style.overflowWrap='anywhere';close.type='button';submit.type='submit';actions.append(close,submit);form.append(label,status,result,actions);dialog.append(node('h2','','Server workspace bindings'),node('p','','This authenticated read-only inspection compares the execution workspace with the separate search and proposal workspace. Paths can be sensitive; they are shown locally and not added to chat or shared with a provider. Browser-selected folders do not configure these paths. Reconfigure server environment variables and restart to change them.'),form);document.body.append(dialog);
  function finish(){closed=true;dialog.close();dialog.remove()}close.onclick=finish;dialog.oncancel=e=>{e.preventDefault();finish()};
  const visible=s=>String(s).replace(/[\u0000-\u001f\u007f-\u009f\u061c\u200e\u200f\u202a-\u202e\u2066-\u2069]/g,c=>'\\u'+c.charCodeAt(0).toString(16).padStart(4,'0'));
  form.onsubmit=async e=>{e.preventDefault();if(busy||!key.value)return;busy=true;key.disabled=submit.disabled=true;status.textContent='Checking local server…';result.textContent='';try{const response=await fetch('/api/actions/workspaces',{method:'POST',headers:{'Content-Type':'application/json','X-ISA-Exec-Token':key.value},body:'{}'});let data;try{data=await response.json()}catch{throw Error('Server does not support authenticated workspace inspection.')}if(!response.ok)throw Error(typeof data.error==='string'?data.error:'Workspace inspection unavailable.');if(typeof data.executionWorkspace!=='string'||!(data.agentWorkspace===null||typeof data.agentWorkspace==='string')||!(data.sameWorkspace===null||typeof data.sameWorkspace==='boolean')||!['host','limited','sandboxed'].includes(data.executionProfile)||(data.agentWorkspace===null&&data.sameWorkspace!==null)||(data.agentWorkspace!==null&&data.sameWorkspace===null))throw Error('Invalid workspace response.');if(closed)return;localExecKey=key.value;const browser=selectedFolder?'Selected browser folder name: '+visible(selectedFolder.name)+' (not a server path)':'No browser folder selected.';result.textContent='Execution workspace: '+visible(data.executionWorkspace)+'\nSearch and proposal workspace: '+(data.agentWorkspace===null?'Not configured':visible(data.agentWorkspace))+'\nComparison: '+(data.sameWorkspace===null?'Unavailable':data.sameWorkspace?'Same canonical directory':'Different canonical directories')+'\nExecution profile: '+data.executionProfile+'\n'+browser;status.textContent=data.sameWorkspace===false?'Workspaces differ. Reviews and writes may target different files.':'Read-only inspection complete. Paths may change if the server is reconfigured.'}catch(error){if(!closed)status.textContent=error.message||'Workspace inspection failed.'}finally{busy=false;if(!closed)key.disabled=submit.disabled=false}};dialog.showModal();key.focus();
}
